using System.Text;
using Lexi.Core.Models;
using Lexi.Core.Morphology;
using Lexi.Core.Search;

namespace Lexi.Dictionary.View;

/// <summary>
/// Renders a <see cref="WordView"/> as Markdown for the Command Palette details pane (compact) and the
/// full entry page. Every meaning block names its source; nothing here is generated by an LLM.
/// </summary>
public static class MarkdownRenderer
{
    public static string Details(WordView v, SearchHit? hit, bool includeTitle = true, bool showGerman = true)
    {
        var sb = new StringBuilder(1024);
        if (includeTitle)
        {
            sb.Append("### ").AppendLine(Escape(v.Title));
        }

        AppendHeaderLine(sb, v, compact: true);
        AppendMatchNote(sb, v, hit);

        AppendBlocks(sb, "中文", v.Chinese, maxSenses: 6, maxBlocks: 2, examples: 0);
        AppendBlocks(sb, "English", v.English, maxSenses: 4, maxBlocks: 1, examples: 0);
        if (v.Word.Lang == Lang.De && showGerman)
        {
            AppendBlocks(sb, "Deutsch", v.German, maxSenses: 3, maxBlocks: 1, examples: 1);
        }

        if (v.Chinese.Count == 0 && v.Word.Lang == Lang.De)
        {
            sb.AppendLine().AppendLine("*暂无可靠的直接中文释义（不做 德→英→中 拼接）。可按 Ctrl+I 让 AI 解释（结果会标注为 AI 生成）。*");
        }

        sb.AppendLine().AppendLine("*Enter：完整词条 · Ctrl+P：发音 · Ctrl+I：AI 解释 · Ctrl+K：更多*");
        return sb.ToString();
    }

    public static string Full(WordView v)
    {
        var sb = new StringBuilder(4096);
        sb.Append("# ").AppendLine(Escape(v.Title));
        AppendHeaderLine(sb, v, compact: false);

        AppendBlocks(sb, "中文释义", v.Chinese, maxSenses: 20, maxBlocks: 4, examples: 0);
        AppendBlocks(sb, "English", v.English, maxSenses: 15, maxBlocks: 4, examples: 2);
        AppendBlocks(sb, "Deutsch", v.German, maxSenses: 15, maxBlocks: 2, examples: 2);

        AppendGrammar(sb, v);

        if (v.Forms.Count > 0)
        {
            sb.AppendLine().AppendLine("**词形 Formen**").AppendLine();
            foreach (var group in v.Forms.GroupBy(f => f.Label).Take(14))
            {
                sb.Append("- ").Append(Escape(group.Key)).Append(": ").AppendLine(Escape(string.Join(", ", group.Select(f => f.Form).Take(8))));
            }
        }

        if (v.Synonyms.Count > 0)
        {
            sb.AppendLine().Append("**近义词**  ").AppendLine(Escape(string.Join(" · ", v.Synonyms)));
        }

        if (v.Related.Count > 0)
        {
            sb.AppendLine().Append("**相关/易混词**  ").AppendLine(Escape(string.Join(" · ", v.Related)));
        }

        if (v.Learner is { } li)
        {
            var parts = new List<string>();
            if (li.Tags is { Count: > 0 })
            {
                parts.Add(string.Join(" ", li.Tags.Select(LearnerTag)));
            }

            if (li.Collins > 0)
            {
                parts.Add("柯林斯 " + new string('★', li.Collins));
            }

            if (li.Oxford)
            {
                parts.Add("牛津 3000");
            }

            if (li.Frq > 0)
            {
                parts.Add($"COCA #{li.Frq}");
            }

            if (li.Bnc > 0)
            {
                parts.Add($"BNC #{li.Bnc}");
            }

            if (parts.Count > 0)
            {
                sb.AppendLine().Append("**学习者信息**  ").Append(string.Join(" · ", parts)).AppendLine(" *(ECDICT)*");
            }
        }

        AppendSources(sb, v);
        return sb.ToString();
    }

    /// <summary>Plain-text definition for the clipboard.</summary>
    public static string PlainDefinition(WordView v)
    {
        var sb = new StringBuilder();
        sb.Append(v.Title);
        var ipa = v.Ipa.FirstOrDefault();
        if (ipa is not null)
        {
            sb.Append(' ').Append(ipa.Text);
        }

        var plural = v.Grammar.FirstOrDefault(g => g.Label.StartsWith("复数", StringComparison.Ordinal));
        if (plural is not null)
        {
            sb.Append(" (Pl. ").Append(plural.Value).Append(')');
        }

        sb.AppendLine();
        foreach (var block in v.Chinese.Take(1).Concat(v.English.Take(1)))
        {
            foreach (var s in block.Senses.Take(5))
            {
                sb.Append("- ").AppendLine(s.Gloss);
            }
        }

        return sb.ToString().TrimEnd();
    }

    private static void AppendHeaderLine(StringBuilder sb, WordView v, bool compact)
    {
        var parts = new List<string>();
        foreach (var p in v.Ipa.Take(compact ? 2 : 4))
        {
            var region = RegionLabel(p.Region);
            parts.Add(region is null ? $"`{p.Text}`" : $"{region} `{p.Text}`");
        }

        foreach (var pos in v.PartsOfSpeech.Take(3))
        {
            parts.Add(WordViewBuilder.PosLabel(pos, v.Word.Lang));
        }

        var gender = v.Grammar.FirstOrDefault(g => g.Label.StartsWith("词性", StringComparison.Ordinal));
        if (gender is not null)
        {
            parts.Add(gender.Value);
        }

        var plural = v.Grammar.FirstOrDefault(g => g.Label.StartsWith("复数", StringComparison.Ordinal));
        if (plural is not null && v.Word.Lang == Lang.De)
        {
            var pl = plural.Value;
            if (v.Cases?.FirstOrDefault(c => c.Case == "nom")?.Plural is { } withArticle)
            {
                pl = withArticle;
            }

            parts.Add("Pl. " + pl);
        }

        if (compact && v.Word.Lang == Lang.De)
        {
            foreach (var (label, shortLabel) in new[] { ("过去时", "Prät."), ("过去分词", "Part. II"), ("助动词", "Hilfsverb"), ("比较级", "Komp."), ("最高级", "Sup.") })
            {
                var g = v.Grammar.FirstOrDefault(x => x.Label.StartsWith(label, StringComparison.Ordinal));
                if (g is not null)
                {
                    parts.Add(shortLabel + " " + g.Value);
                }
            }
        }

        if (parts.Count > 0)
        {
            sb.AppendLine().AppendLine(string.Join(" · ", parts.Select(EscapeKeepCode)));
        }

        if (v.Ipa.Count > 0)
        {
            sb.AppendLine().Append("*音标来源：").Append(Escape(v.Ipa[0].Source.Name)).AppendLine("*");
        }
    }

    private static void AppendMatchNote(StringBuilder sb, WordView v, SearchHit? hit)
    {
        if (hit is null)
        {
            return;
        }

        string? note = hit.Kind switch
        {
            MatchKind.Form or MatchKind.FormFold or MatchKind.FormTranslit =>
                $"**{Escape(hit.Matched ?? string.Empty)}** 是 **{Escape(v.Word.Word)}** 的{FormDescriber.Describe(hit.FormTags, v.Word.Lang)}",
            MatchKind.Translit => $"按德语转写匹配：ae/oe/ue/ss → ä/ö/ü/ß",
            MatchKind.Fold => "忽略变音符号匹配",
            MatchKind.Fuzzy or MatchKind.FuzzyForm => $"拼写纠正（编辑距离 {hit.Distance}）",
            _ => null,
        };
        if (note is not null)
        {
            sb.AppendLine().Append("> ").AppendLine(note);
        }
    }

    private static void AppendBlocks(StringBuilder sb, string heading, IReadOnlyList<MeaningBlock> blocks, int maxSenses, int maxBlocks, int examples)
    {
        if (blocks.Count == 0)
        {
            return;
        }

        foreach (var block in blocks.Take(maxBlocks))
        {
            var kind = block.Kind == "translation" ? "（按义项的对应词）" : string.Empty;
            sb.AppendLine().Append("**").Append(heading).Append("**").Append(kind).Append("  *— ").Append(Escape(block.Source.Name)).AppendLine("*").AppendLine();
            var n = 0;
            foreach (var s in block.Senses)
            {
                if (n++ >= maxSenses)
                {
                    sb.AppendLine($"- … 共 {block.Senses.Count} 项");
                    break;
                }

                var number = s.Number is null ? $"{n}." : $"{s.Number}.";
                sb.Append(number).Append(' ');
                if (s.Labels is { Count: > 0 })
                {
                    sb.Append('*').Append(Escape(string.Join(", ", s.Labels))).Append("* ");
                }

                sb.Append(Escape(s.Gloss ?? string.Empty));
                if (examples > 0 && s.Examples is { Count: > 0 })
                {
                    foreach (var ex in s.Examples.Where(e => !IsNymNote(e.Text)).Take(examples))
                    {
                        // A hard line break keeps the example inside the list item, so it wraps with the gloss
                        // (a blockquote nested in a list item does not wrap in Command Palette's Markdown view).
                        sb.AppendLine("  ").Append("   *").Append(Escape(ex.Text.Trim()));
                        if (!string.IsNullOrEmpty(ex.Translation))
                        {
                            sb.Append(" — ").Append(Escape(ex.Translation.Trim()));
                        }

                        sb.Append('*');
                    }
                }

                sb.AppendLine();
            }
        }
    }

    /// <summary>Wiktionary sometimes files "Synonyms: …" / "Near-synonym: …" notes as usage examples.</summary>
    private static bool IsNymNote(string text)
    {
        var colon = text.IndexOf(':', StringComparison.Ordinal);
        if (colon is <= 0 or >= 20)
        {
            return false;
        }

        var label = text.AsSpan(0, colon).Trim();
        return label.EndsWith("nym", StringComparison.OrdinalIgnoreCase) || label.EndsWith("nyms", StringComparison.OrdinalIgnoreCase);
    }

    private static void AppendGrammar(StringBuilder sb, WordView v)
    {
        if (v.Grammar.Count == 0 && v.Cases is null && v.GrammarSummary is null)
        {
            return;
        }

        sb.AppendLine().Append("**语法 Grammatik**");
        if (v.GrammarSource is not null)
        {
            sb.Append("  *— ").Append(Escape(v.GrammarSource.Name)).Append('*');
        }

        sb.AppendLine().AppendLine();
        foreach (var g in v.Grammar)
        {
            sb.Append("- ").Append(Escape(g.Label)).Append("：").AppendLine(Escape(g.Value));
        }

        if (v.Cases is { Count: > 0 })
        {
            sb.AppendLine().AppendLine("| Kasus | Singular | Plural |").AppendLine("|---|---|---|");
            foreach (var c in v.Cases)
            {
                sb.Append("| ").Append(CaseName(c.Case)).Append(" | ").Append(Escape(c.Singular ?? "—")).Append(" | ").Append(Escape(c.Plural ?? "—")).AppendLine(" |");
            }
        }

        if (v.GrammarSummary is not null)
        {
            sb.AppendLine().Append("*").Append(Escape(v.GrammarSummary)).AppendLine("* *(Wiktionary EN)*");
        }
    }

    private static void AppendSources(StringBuilder sb, WordView v)
    {
        sb.AppendLine().AppendLine("---").AppendLine().AppendLine("**来源与许可**").AppendLine();
        foreach (var s in v.Sources)
        {
            sb.Append("- [").Append(Escape(s.Name)).Append("](").Append(s.Url).Append(") — ").Append(Escape(s.License));
            if (s.Version is not null)
            {
                sb.Append(" (").Append(Escape(s.Version)).Append(')');
            }

            sb.AppendLine();
        }

        if (v.Audio.Count > 0)
        {
            sb.Append("- 录音：Wikimedia Commons（").Append(Escape(string.Join(", ", v.Audio.Take(3).Select(a => a.File)))).AppendLine("，各文件单独授权）");
        }

        if (v.RawRefs.Count > 0)
        {
            sb.Append("- 原始数据：`").Append(string.Join("`, `", v.RawRefs.Take(6))).AppendLine("`");
        }
    }

    private static string CaseName(string c) => c switch
    {
        "nom" => "Nominativ",
        "gen" => "Genitiv",
        "dat" => "Dativ",
        "acc" => "Akkusativ",
        _ => c,
    };

    private static string? RegionLabel(string? region) => region switch
    {
        "UK" => "英",
        "US" => "美",
        "AU" => "澳",
        "AT" => "奥",
        "CH" => "瑞",
        _ => null,
    };

    private static string LearnerTag(string tag) => tag switch
    {
        "zk" => "中考",
        "gk" => "高考",
        "cet4" => "四级",
        "cet6" => "六级",
        "ky" => "考研",
        "toefl" => "TOEFL",
        "ielts" => "IELTS",
        "gre" => "GRE",
        _ => tag,
    };

    /// <summary>Escapes Markdown control characters in dictionary text.</summary>
    public static string Escape(string text)
    {
        if (text.AsSpan().IndexOfAny("\\`*_[]<>#|~") < 0)
        {
            return text;
        }

        var sb = new StringBuilder(text.Length + 8);
        foreach (var c in text)
        {
            if (c is '\\' or '`' or '*' or '_' or '[' or ']' or '<' or '>' or '#' or '|' or '~')
            {
                sb.Append('\\');
            }

            sb.Append(c);
        }

        return sb.ToString();
    }

    // Header parts already contain code spans we generated ourselves.
    private static string EscapeKeepCode(string part) => part.Contains('`', StringComparison.Ordinal) ? part : Escape(part);
}
